    /** ink (#FFF3EFE9) */
    public static final int INK = 0xFFF3EFE9;
    /** ink-soft (#FFB3ABB0) */
    public static final int INK_SOFT = 0xFFB3ABB0;
    /** ink-faint (#FF837B82) */
    public static final int INK_FAINT = 0xFF837B82;
    /** vinyl (#FFFBFAF7) */
    public static final int VINYL = 0xFFFBFAF7;
    /** vinyl-ink (#FF17141A) */
